const { withAppBuildGradle } = require('expo/config-plugins');

const START_MARKER = '// @generated by with-monorepo-bundle-inputs';
const END_MARKER = '// @end generated by with-monorepo-bundle-inputs';

const GRADLE_BLOCK = `${START_MARKER}
// React Native tracks only the Expo app directory as bundle input by default.
// Metro also resolves Dina's workspace packages and shared model catalog, so
// declare those inputs to prevent stale release bundles after package changes.
def dinaMonorepoRoot = rootDir.getAbsoluteFile().getParentFile().getParentFile().getParentFile()
def dinaSharedBundleSources = files(
    fileTree(new File(dinaMonorepoRoot, "packages")) {
        include "**/*.js", "**/*.jsx", "**/*.ts", "**/*.tsx", "**/*.json"
        exclude "**/node_modules/**", "**/build/**", "**/dist/**", "**/coverage/**"
    },
    new File(dinaMonorepoRoot, "config/models.json"),
    new File(dinaMonorepoRoot, "package.json"),
    new File(dinaMonorepoRoot, "package-lock.json")
)

tasks.withType(com.facebook.react.tasks.BundleHermesCTask).configureEach { task ->
    task.inputs.files(dinaSharedBundleSources)
        .withPathSensitivity(org.gradle.api.tasks.PathSensitivity.RELATIVE)
}
${END_MARKER}`;

function replaceGeneratedBlock(contents) {
  const start = contents.indexOf(START_MARKER);
  const end = contents.indexOf(END_MARKER);
  if (start === -1 && end === -1) {
    return `${contents.trimEnd()}\n\n${GRADLE_BLOCK}\n`;
  }
  if (start === -1 || end === -1 || end < start) {
    throw new Error('Malformed with-monorepo-bundle-inputs block in android/app/build.gradle');
  }

  const after = end + END_MARKER.length;
  return `${contents.slice(0, start)}${GRADLE_BLOCK}${contents.slice(after)}`;
}

module.exports = function withMonorepoBundleInputs(config) {
  return withAppBuildGradle(config, (mod) => {
    if (mod.modResults.language !== 'groovy') {
      throw new Error('with-monorepo-bundle-inputs requires a Groovy app/build.gradle');
    }
    mod.modResults.contents = replaceGeneratedBlock(mod.modResults.contents);
    return mod;
  });
};

module.exports.replaceGeneratedBlock = replaceGeneratedBlock;
